// === HIER PFLEGEN ===
const CONFIG = {
  // SKU(s) des Buchs – Honesty 3 EXKLUSIVAUSGABE
  targets: [
    { sku: 'EX-2026-02-03' },
  ],

  // Kundenbenachrichtigung an/aus: true = Shopify schickt die Storno-Mail bzw. die Mail zur Bestelländerung
  notifyCustomer: true,

  // true = es wird NICHTS geändert, der Flow ordnet nur ein und mailt den Report.
  // Erst auf false stellen, wenn der Trockenlauf-Report passt.
  trockenlauf: false,

  // Versandkosten für EINE Sendung mit EINEM Produkt, je Lieferland (ISO-Code).
  // BeSpoke lässt sich nicht abfragen, deshalb hier pflegen. Land fehlt/null = wird nicht bearbeitet.
  //  - Einzelversand: dieser Betrag wird mit erstattet (einmal je Bestellung)
  //  - Sammelversand, danach nur noch 1 Produkt: Erstattung = bezahlter Sammelversand − dieser Betrag
  // TODO vor dem ersten scharfen Lauf eintragen, z. B. DE: 4.99
  versandkosten: { DE: null, AT: null, CH: null },

  // Titel der Versandarten, wie sie in der Bestellung stehen
  versandartEinzel: ['Einzelversand'],
  versandartSammel: ['Sammelversand'],
  // Kostenloser Versand: nur das Buch raus, keine Versanderstattung
  versandartKostenlos: ['Kostenlose Lieferung'],

  // Importierte Bestellungen (WooCommerce via Matrixify) – dafür kommt ein eigener Flow
  ignorierteQuellen: ['Matrixify App'],

  // Storno-Grund in Shopify. INVENTORY = nicht lieferbar.
  // Weitere Werte: CUSTOMER, DECLINED, FRAUD, OTHER, STAFF_ERROR
  stornoGrund: 'INVENTORY',

  // Bestand beim Stornieren/Entfernen zurückbuchen?
  restock: false,

  // Einzelne Bestellungen ausschließen: Bestellnummer ('BB-12345') oder orderId
  ausnahmen: [],

  // Interne Notiz, für Kunden nicht sichtbar. SKU und Versanderstattung werden angehängt (max. 255 Zeichen)
  staffNote: 'Automatische Bearbeitung: Buch nicht mehr lieferbar. Erstattung über Refund-Flow.',

  // Tag nach erfolgreicher Bearbeitung – macht die Bestellungen für den Refund-Flow filterbar
  tag: `n8n-api-${$workflow.id}`
};

const ungueltig = CONFIG.targets.filter(t => !String(t.sku || '').trim() || String(t.sku).includes('HIER-'));
if (!CONFIG.targets.length || ungueltig.length) {
  throw new Error('Config: SKU des Buchs noch nicht eingetragen – Flow ist nur vorbereitet.');
}

// CSV-Binary unverändert durchreichen, Config für alle Folge-Nodes anhängen
return $input.all().map(i => ({
  json: { ...i.json, config: CONFIG },
  binary: i.binary
}));

// Erwartet den Shopify-Bestellexport (CSV) mit allen betroffenen Bestellungen.
// Eine Zeile pro Line-Item; 'Id' steht nur in der ersten Zeile einer Bestellung
// -> forward-fill innerhalb derselben Bestellnummer ('Name').
const items = $input.all().map(i => i.json);
let lastName = null;
let lastId = null;
const namen = new Set();
const namenMitId = new Set();
const seen = new Set();
const orders = [];
for (const row of items) {
  const name = String(row['Name'] || '').trim();
  const idRaw = String(row['Id'] ?? row['ID'] ?? row['id'] ?? '').trim();
  if (!name) continue;
  namen.add(name);
  if (name !== lastName) { lastName = name; lastId = null; }
  if (idRaw) lastId = idRaw;
  if (!lastId) continue;
  namenMitId.add(name);
  if (seen.has(lastId)) continue;
  seen.add(lastId);
  orders.push({ orderId: Number(lastId), orderName: name });
}

// Die CSV ist die vollständige Liste – eine Bestellung ohne Id würde sonst stillschweigend fehlen
const ohneId = [...namen].filter(n => !namenMitId.has(n));
if (ohneId.length) {
  throw new Error(`CSV: ${ohneId.length} Bestellung(en) ohne 'Id', z. B. ${ohneId.slice(0, 10).join(', ')} – bitte den Shopify-Bestellexport verwenden.`);
}
if (!orders.length) {
  throw new Error("CSV enthält keine Bestellungen mit den Spalten 'Name' und 'Id' – bitte den Shopify-Bestellexport verwenden.");
}

return orders.map(o => ({ json: o }));

// Listen einmalig leeren, Token durchreichen, alle Bestellungen weitergeben.
const staticData = $getWorkflowStaticData('global');
staticData.toFix = [];
staticData.skipped = [];
staticData.done = [];

const token = $json.access_token;
const orders = $('Bestellungen extrahieren (dedupe)').all().map(i => i.json);

return orders.map(o => ({
  json: { ...o, accessToken: token }
}));

// Ordnet jede CSV-Bestellung genau einem Status zu:
// Kandidat (toFix, aktion STORNO oder ENTFERNEN) oder übersprungen (skipped)
const response = $input.first().json;
const src = $('Loop je Bestellung (CSV)').first().json;
const order = response.body?.order || response.order || null;
const config = $('Config').first().json.config;
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.toFix)) staticData.toFix = [];
if (!Array.isArray(staticData.skipped)) staticData.skipped = [];

const fertig = () => [{ json: { kandidaten: staticData.toFix.length, uebersprungen: staticData.skipped.length } }];

if (!order) {
  // GET fehlgeschlagen (z. B. falsche Id in der CSV) – der Lauf geht weiter
  staticData.skipped.push({
    orderId: src.orderId,
    orderName: src.orderName,
    positionen: [],
    weitere: [],
    status: 'NICHT_GEFUNDEN',
    grund: 'Bestellung nicht abrufbar: ' + String(response.error?.message || JSON.stringify(response)).slice(0, 200)
  });
  return fertig();
}

const runden = x => Math.round(x * 100) / 100;
const ZIEL_SKUS = new Set(config.targets.map(t => String(t.sku).trim()));
const istBuch = li => ZIEL_SKUS.has(String(li.sku || '').trim());
const normTitel = s => String(s || '').trim().toLowerCase();

// current_quantity: entfernte Positionen behalten quantity, current_quantity ist 0
const aktiv = (order.line_items || []).filter(li => Number(li.current_quantity) > 0);
const buch = aktiv.filter(istBuch);
const weitere = aktiv.filter(li => !istBuch(li));
const versandLinien = (order.shipping_lines || []).filter(sl => !sl.is_removed);
const land = order.shipping_address?.country_code || null;

const position = li => ({
  lineItemId: li.id,
  sku: li.sku,
  title: li.title,
  menge: Number(li.current_quantity),
  versendbar: Number(li.fulfillable_quantity)
});

// Wert der Buch-Positionen nach Rabatten – zur Kontrolle des hinterlegten Refunds
const buchWert = runden(buch.reduce((s, li) =>
  s + Number(li.price) * Number(li.current_quantity)
    - (li.discount_allocations || []).reduce((d, a) => d + Number(a.amount || 0), 0), 0));

const datensatz = {
  orderId: order.id,
  orderName: order.name,
  createdAt: order.created_at,
  quelle: order.source_name || '',
  land,
  financialStatus: order.financial_status,
  currency: order.currency,
  bestellwert: order.current_total_price,
  saldoVorher: order.total_outstanding,
  versandart: versandLinien.map(sl => sl.title).join(' + '),
  versandBezahlt: runden(versandLinien.reduce((s, sl) => s + Number(sl.discounted_price ?? sl.price ?? 0), 0)),
  positionen: buch.map(position),
  weitere: weitere.map(position)
};

const ausnahme = (config.ausnahmen || []).some(a =>
  String(a) === String(order.id) || String(a) === order.name
);

const ueberspringen = (status, grund) => {
  staticData.skipped.push({ ...datensatz, status, grund });
  return fertig();
};

if (order.cancelled_at) return ueberspringen('BEREITS_STORNIERT', 'Storniert am ' + order.cancelled_at);
if ((config.ignorierteQuellen || []).includes(datensatz.quelle)) {
  return ueberspringen('WC_IMPORT', `Importierte Bestellung (Quelle: ${datensatz.quelle}) – eigener Flow folgt`);
}
if (ausnahme) return ueberspringen('AUSNAHME', 'Bestellung steht in Config.ausnahmen');
if (!buch.length) return ueberspringen('NICHT_BETROFFEN', 'Buch nicht (mehr) aktiv in der Bestellung – CSV prüfen');
if (buch.some(li => Number(li.fulfillable_quantity) < Number(li.current_quantity))) {
  return ueberspringen('VERSENDET', 'Buch bereits (teil-)versendet – manuell prüfen');
}

const kandidat = (aktion, fall, versand) => {
  // STORNO: der bezahlte Betrag wird offen; ENTFERNEN: Buch nach Rabatten + Versanderstattung
  const erwartet = aktion === 'STORNO'
    ? runden(Number(order.current_total_price) - Number(order.total_outstanding))
    : runden(buchWert + (versand?.erstattung || 0));
  staticData.toFix.push({ ...datensatz, aktion, fall, versand, erwarteteErstattung: erwartet });
  return fertig();
};

// Nur das Buch in der Bestellung: vollständig stornieren
if (!weitere.length) return kandidat('STORNO', 'NUR_BUCH', null);

// Mehrere Produkte: Buch entfernen, Versand nach Versandart
if (versandLinien.length !== 1) {
  return ueberspringen('VERSAND_PRUEFEN', `${versandLinien.length} Versandpositionen – manuell prüfen`);
}
const sl = versandLinien[0];
const titel = normTitel(sl.title);
const istVersandart = liste => (liste || []).map(normTitel).includes(titel);
const bezahlt = Number(sl.discounted_price ?? sl.price);
const kosten = config.versandkosten?.[land];
const hatKosten = typeof kosten === 'number' && Number.isFinite(kosten);
const ohneKosten = () => ueberspringen('VERSAND_PRUEFEN', `Keine Versandkosten für Land ${land} in Config.versandkosten`);
// Nur relevant, wenn der Versand geändert wird – sonst bleibt die Versandposition unberührt
const rabattiert = () => Number(sl.price) !== bezahlt
  ? ueberspringen('VERSAND_PRUEFEN', `Versand rabattiert (${sl.price} → ${bezahlt}) – manuell prüfen`)
  : null;
const versand = (erstattung, neuerPreis) => ({
  shippingLineId: sl.id, titel: sl.title, bezahlt, erstattung: runden(erstattung), neuerPreis: runden(neuerPreis)
});

if (istVersandart(config.versandartKostenlos)) {
  return kandidat('ENTFERNEN', 'KOSTENLOSE_LIEFERUNG', versand(0, bezahlt));
}

if (istVersandart(config.versandartEinzel)) {
  if (!hatKosten) return ohneKosten();
  const r = rabattiert(); if (r) return r;
  if (bezahlt < kosten) {
    return ueberspringen('VERSAND_PRUEFEN', `Bezahlter Einzelversand ${bezahlt} kleiner als Config ${kosten} – manuell prüfen`);
  }
  return kandidat('ENTFERNEN', 'EINZELVERSAND', versand(kosten, bezahlt - kosten));
}

if (istVersandart(config.versandartSammel)) {
  // Was nach dem Entfernen noch verschickt werden muss (Stückzahl)
  const restEinheiten = weitere
    .filter(li => li.requires_shipping !== false)
    .reduce((s, li) => s + Number(li.current_quantity), 0);

  if (restEinheiten >= 2) return kandidat('ENTFERNEN', 'SAMMELVERSAND', versand(0, bezahlt));
  if (restEinheiten === 1) {
    if (!hatKosten) return ohneKosten();
    const r = rabattiert(); if (r) return r;
    if (bezahlt < kosten) {
      return ueberspringen('VERSAND_PRUEFEN', `Bezahlter Sammelversand ${bezahlt} kleiner als Config ${kosten} – manuell prüfen`);
    }
    return kandidat('ENTFERNEN', 'SAMMELVERSAND_EIN_PRODUKT', versand(bezahlt - kosten, kosten));
  }
  return ueberspringen('VERSAND_PRUEFEN', 'Nach dem Entfernen bleibt kein Versandprodukt übrig – manuell prüfen');
}

return ueberspringen('VERSANDART_UNBEKANNT', `Versandart "${sl.title}" – vorerst nicht bearbeitet`);

// Ein Item je zu bearbeitender Bestellung
const config = $('Config').first().json.config;
const staticData = $getWorkflowStaticData('global');
const collected = staticData.toFix || [];

// Trockenlauf oder keine Kandidaten: Steuer-Item ohne orderGid -> IF leitet direkt zum Report
if (config.trockenlauf || !collected.length) {
  return [{ json: { modus: config.trockenlauf ? 'TROCKENLAUF' : 'KEINE_KANDIDATEN', bestellungen: collected.length } }];
}

return collected.map(order => ({
  json: {
    orderId: order.orderId,
    orderName: order.orderName,
    orderGid: `gid://shopify/Order/${order.orderId}`,
    aktion: order.aktion,
    fall: order.fall,
    versand: order.versand,
    erwarteteErstattung: order.erwarteteErstattung,
    saldoVorher: Number(order.saldoVorher),
    skus: [...new Set(order.positionen.map(p => p.sku))],
    // CalculatedLineItem-ID = LineItem-ID für bestehende Positionen
    lineItemGids: order.positionen.map(p => `gid://shopify/CalculatedLineItem/${p.lineItemId}`)
  }
}));

// TESTGATE: verarbeitet nur die erste gefundene Bestellung.
// Für den Vollauf diesen Node deaktivieren oder löschen.
return $input.all().slice(0, 1);

const item = $('Loop Over Items').first().json;
const config = $('Config').first().json.config;

// refund: false – die Erstattung übernimmt der Refund-Flow.
// Autorisierte, noch nicht eingezogene Zahlungen gibt Shopify beim Storno trotzdem frei.
const body = {
  query: `mutation orderCancel($orderId: ID!, $reason: OrderCancelReason!, $restock: Boolean!, $notifyCustomer: Boolean, $staffNote: String) {
    orderCancel(orderId: $orderId, reason: $reason, refund: false, restock: $restock, notifyCustomer: $notifyCustomer, staffNote: $staffNote) {
      job { id done }
      orderCancelUserErrors { field message code }
    }
  }`,
  variables: {
    orderId: item.orderGid,
    reason: config.stornoGrund,
    restock: config.restock,
    notifyCustomer: config.notifyCustomer,
    staffNote: `${config.staffNote} SKU: ${item.skus.join(', ')}`.slice(0, 255)
  }
};

return [{
  json: {
    accessToken: $('Token holen 2').first().json.access_token,
    gqlBody: JSON.stringify(body)
  }
}];

const resp = $input.first().json;
const src = $('Loop Over Items').first().json;
const payload = resp?.data?.orderCancel;

// Bewusst kein throw: ein abgelehnter Storno ändert nichts an der Bestellung,
// der Lauf geht mit der nächsten weiter. Die Shopify-Meldung steht im Report.
const fehler = [
  ...(resp?.errors || []).map(e => e.message),
  ...(payload?.orderCancelUserErrors || []).map(e => (e.code ? e.code + ': ' : '') + e.message)
];
if (!fehler.length && !payload?.job?.id) {
  fehler.push('Kein Storno-Job erhalten: ' + JSON.stringify(resp).slice(0, 300));
}

const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.done)) sd.done = [];
sd.done.push({
  orderId: src.orderId,
  orderName: src.orderName,
  status: fehler.length ? 'FEHLER' : 'STORNIERT',
  grund: fehler.join(' | ').slice(0, 500),
  jobId: payload?.job?.id || null,
  stornoBestaetigt: false,
  saldoNachher: null,
  refundHinterlegt: null,
  finanzstatusNachher: null,
  tagGesetzt: false,
  bearbeitetAm: new Date().toISOString()
});

return [{ json: { ...src, stornoAngenommen: !fehler.length } }];

const resp = $input.first().json;
const src = $('Storno-Ergebnis prüfen').first().json;
const order = resp?.data?.order || null;

// Der Storno läuft bei Shopify als Hintergrund-Job. "Nicht bestätigt" heißt
// nicht gescheitert – dann in Shopify nachsehen.
const bestaetigt = !!order?.cancelledAt;

const sd = $getWorkflowStaticData('global');
const eintrag = (sd.done || []).find(d => d.orderId === src.orderId);
if (eintrag) {
  eintrag.stornoBestaetigt = bestaetigt;
  eintrag.finanzstatusNachher = order?.displayFinancialStatus || null;
  const saldo = order?.totalOutstandingSet?.shopMoney?.amount;
  eintrag.saldoNachher = (saldo === undefined || saldo === null) ? null : Number(saldo);
  const vorher = Number(src.saldoVorher);
  if (eintrag.saldoNachher !== null && Number.isFinite(vorher)) {
    eintrag.refundHinterlegt = Math.round((vorher - eintrag.saldoNachher) * 100) / 100;
  }
  if (!bestaetigt) {
    eintrag.grund = 'Storno-Job angenommen, nach 3 s noch nicht bestätigt – in Shopify prüfen';
  } else if (eintrag.refundHinterlegt !== null && Math.abs(eintrag.refundHinterlegt - src.erwarteteErstattung) > 0.01) {
    eintrag.grund = `Hinterlegt ${eintrag.refundHinterlegt.toFixed(2)}, erwartet ${src.erwarteteErstattung.toFixed(2)} – prüfen`;
  }
}

return [{ json: { ...src, stornoBestaetigt: bestaetigt } }];

const item = $('Loop Over Items').first().json;

const body = {
  query: `mutation orderEditBegin($id: ID!) {
    orderEditBegin(id: $id) {
      calculatedOrder {
        id
        originalOrder { totalOutstandingSet { shopMoney { amount currencyCode } } }
        lineItems(first: 100) { edges { node { id sku quantity } } }
        shippingLines { id title stagedStatus price { shopMoney { amount currencyCode } } }
      }
      userErrors { field message }
    }
  }`,
  variables: { id: item.orderGid }
};

return [{
  json: {
    accessToken: $('Token holen 2').first().json.access_token,
    gqlBody: JSON.stringify(body)
  }
}];

const resp = $input.first().json;
const src = $('Loop Over Items').first().json;
const config = $('Config').first().json.config;

const fehler = [];
const begin = resp?.data?.orderEditBegin;
fehler.push(...(resp?.errors || []).map(e => e.message));
fehler.push(...(begin?.userErrors || []).map(e => e.message));
const calc = begin?.calculatedOrder || null;
if (!fehler.length && !calc?.id) fehler.push('Keine calculatedOrder erhalten');

let gqlBody = null;
let saldoVorher = null;
if (!fehler.length) {
  // Buch-Positionen: exakt die gefundenen, noch aktiven
  const aktive = (calc.lineItems?.edges || []).map(e => e.node)
    .filter(n => Number(n.quantity) > 0 && src.lineItemGids.includes(n.id));
  if (aktive.length !== src.lineItemGids.length) {
    fehler.push(`${aktive.length} von ${src.lineItemGids.length} Buch-Positionen im Edit gefunden`);
  }

  // Bestehende Versandposition (nicht im Edit hinzugefügt/entfernt) mit demselben Titel
  let versandLinie = null;
  if (src.versand?.erstattung > 0) {
    const kandidaten = (calc.shippingLines || []).filter(s =>
      !['ADDED', 'REMOVED'].includes(s.stagedStatus) &&
      String(s.title).trim() === String(src.versand.titel).trim()
    );
    if (kandidaten.length !== 1) fehler.push(`${kandidaten.length} passende Versandpositionen im Edit gefunden`);
    else versandLinie = kandidaten[0];
  }

  const vorher = calc.originalOrder?.totalOutstandingSet?.shopMoney;
  saldoVorher = vorher ? Number(vorher.amount) : null;

  if (!fehler.length) {
    // Eine Anfrage, je Schritt ein Alias. Top-Level-Mutationen laufen nacheinander im selben Edit.
    // Versand: bestehende Position entfernen, neue mit demselben Titel und dem neuen Preis anlegen.
    const defs = ['$id: ID!', '$restock: Boolean'];
    const felder = [];
    const variables = { id: calc.id, restock: config.restock };
    aktive.forEach((li, i) => {
      defs.push(`$li${i}: ID!`);
      variables['li' + i] = li.id;
      felder.push(`p${i}: orderEditSetQuantity(id: $id, lineItemId: $li${i}, quantity: 0, restock: $restock) {
      calculatedLineItem { id quantity }
      userErrors { field message }
    }`);
    });
    if (versandLinie) {
      defs.push('$sl: ID!');
      variables.sl = versandLinie.id;
      felder.push(`vr: orderEditRemoveShippingLine(id: $id, shippingLineId: $sl) {
      userErrors { field message }
    }`);
      if (src.versand.neuerPreis > 0) {
        defs.push('$slTitel: String!', '$slPreis: Decimal!', '$slWaehrung: CurrencyCode!');
        variables.slTitel = versandLinie.title;
        variables.slPreis = src.versand.neuerPreis.toFixed(2);
        variables.slWaehrung = versandLinie.price?.shopMoney?.currencyCode || 'EUR';
        felder.push(`va: orderEditAddShippingLine(id: $id, shippingLine: { title: $slTitel, price: { amount: $slPreis, currencyCode: $slWaehrung } }) {
      calculatedShippingLine { id title price { shopMoney { amount currencyCode } } }
      userErrors { field message }
    }`);
      }
    }
    gqlBody = JSON.stringify({
      query: `mutation buchEntfernen(${defs.join(', ')}) {\n    ${felder.join('\n    ')}\n  }`,
      variables
    });
  }
}

// Bewusst kein throw: ohne Commit bleibt die Bestellung unverändert, der Lauf geht weiter.
if (fehler.length) {
  const sd = $getWorkflowStaticData('global');
  if (!Array.isArray(sd.done)) sd.done = [];
  sd.done.push({
    orderId: src.orderId, orderName: src.orderName, status: 'FEHLER',
    grund: ('orderEditBegin: ' + fehler.join(' | ')).slice(0, 500),
    saldoNachher: null, refundHinterlegt: null, finanzstatusNachher: null,
    tagGesetzt: false, bearbeitetAm: new Date().toISOString()
  });
}

return [{
  json: {
    ...src,
    calcOrderId: calc?.id || null,
    saldoVorher,
    editVorbereitet: !fehler.length,
    accessToken: $('Token holen 2').first().json.access_token,
    gqlBody
  }
}];

const resp = $input.first().json;
const { gqlBody, accessToken, ...src } = $('Edit vorbereiten').first().json;
const data = resp?.data || {};

// Alle Aliase auswerten: GraphQL-Fehler, userErrors, Menge 0
const fehler = [...(resp?.errors || []).map(e => e.message)];
for (const [alias, r] of Object.entries(data)) {
  for (const e of (r?.userErrors || [])) fehler.push(`${alias}: ${e.message}`);
  if (alias.startsWith('p') && r?.calculatedLineItem && Number(r.calculatedLineItem.quantity) !== 0) {
    fehler.push(`${alias}: Menge nicht 0`);
  }
}
if (!fehler.length && !Object.keys(data).length) fehler.push('Leere Antwort: ' + JSON.stringify(resp).slice(0, 300));

// Bewusst kein throw: ohne Commit bleibt die Bestellung unverändert.
if (fehler.length) {
  const sd = $getWorkflowStaticData('global');
  if (!Array.isArray(sd.done)) sd.done = [];
  sd.done.push({
    orderId: src.orderId, orderName: src.orderName, status: 'FEHLER',
    grund: ('Edit (nicht gespeichert): ' + fehler.join(' | ')).slice(0, 500),
    saldoNachher: null, refundHinterlegt: null, finanzstatusNachher: null,
    tagGesetzt: false, bearbeitetAm: new Date().toISOString()
  });
}

return [{ json: { ...src, editFehlerfrei: !fehler.length } }];

const item = $input.first().json;
const config = $('Config').first().json.config;

const versandInfo = item.versand?.erstattung > 0 ? ` Versanderstattung: ${item.versand.erstattung.toFixed(2)}` : '';

const body = {
  query: `mutation orderEditCommit($id: ID!, $notifyCustomer: Boolean, $staffNote: String) {
    orderEditCommit(id: $id, notifyCustomer: $notifyCustomer, staffNote: $staffNote) {
      order {
        id
        name
        displayFinancialStatus
        totalOutstandingSet { shopMoney { amount currencyCode } }
      }
      userErrors { field message }
    }
  }`,
  variables: {
    id: item.calcOrderId,
    notifyCustomer: config.notifyCustomer,
    staffNote: `${config.staffNote} SKU: ${item.skus.join(', ')}.${versandInfo}`.slice(0, 255)
  }
};

return [{
  json: {
    ...item,
    accessToken: $('Token holen 2').first().json.access_token,
    gqlBody: JSON.stringify(body)
  }
}];

const resp = $input.first().json;
const src = $('Edit-Ergebnis prüfen').first().json;
const commit = resp?.data?.orderEditCommit;

const fehler = [
  ...(resp?.errors || []).map(e => e.message),
  ...(commit?.userErrors || []).map(e => e.message)
];
const order = commit?.order || null;
if (!fehler.length && !order) fehler.push('Kein Order-Objekt nach Commit: ' + JSON.stringify(resp).slice(0, 300));

// totalOutstanding: negativ = wir schulden dem Kunden (Shopify: "Rückerstattung ausstehend").
// Differenz vorher/nachher = durch diesen Edit hinterlegter Refund (Buch + Versanderstattung).
const nachherRoh = order?.totalOutstandingSet?.shopMoney?.amount;
const saldoNachher = (nachherRoh === undefined || nachherRoh === null) ? null : Number(nachherRoh);
const refundHinterlegt = (saldoNachher !== null && src.saldoVorher !== null)
  ? Math.round((src.saldoVorher - saldoNachher) * 100) / 100
  : null;

let grund = fehler.join(' | ');
if (!fehler.length && refundHinterlegt !== null && Math.abs(refundHinterlegt - src.erwarteteErstattung) > 0.01) {
  grund = `Hinterlegt ${refundHinterlegt.toFixed(2)}, erwartet ${src.erwarteteErstattung.toFixed(2)} – prüfen`;
}

const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.done)) sd.done = [];
sd.done.push({
  orderId: src.orderId,
  orderName: src.orderName,
  status: fehler.length ? 'FEHLER' : 'ENTFERNT',
  grund: grund.slice(0, 500),
  saldoVorher: src.saldoVorher,
  saldoNachher,
  refundHinterlegt,
  finanzstatusNachher: order?.displayFinancialStatus || null,
  tagGesetzt: false,
  bearbeitetAm: new Date().toISOString()
});

return [{ json: { ...src, commitOk: !fehler.length, orderGid: order?.id || src.orderGid } }];

const resp = $input.first().json;
// Aus dem Loop, nicht aus einem der beiden Zweige – der jeweils andere enthält Daten der Vorrunde
const src = $('Loop Over Items').first().json;

// Bewusst kein throw: die Bearbeitung ist durch, ein fehlender Tag soll den Loop nicht stoppen.
const errs = [
  ...(resp?.error ? [resp.error] : []),
  ...(resp?.errors || []),
  ...(resp?.data?.tagsAdd?.userErrors || [])
];

const sd = $getWorkflowStaticData('global');
const eintrag = (sd.done || []).find(d => d.orderId === src.orderId);
if (eintrag) {
  eintrag.tagGesetzt = !errs.length;
  if (errs.length) eintrag.tagFehler = JSON.stringify(errs).slice(0, 300);
}

return [{ json: { orderId: src.orderId, orderName: src.orderName, tagGesetzt: !errs.length } }];

// Abschluss-Report: genau eine Zeile je Bestellung aus der CSV
const config = $('Config').first().json.config;
const sd = $getWorkflowStaticData('global');
const gefunden = sd.toFix || [];
const erledigt = sd.done || [];
const skipped = sd.skipped || [];

// Alle Zeilen mit denselben Spalten, sonst wird die CSV uneinheitlich
const LEER = {
  orderName: '', orderId: '', status: '', fall: '', grund: '', skus: '', menge: '', weiterePositionen: '',
  land: '', versandart: '', versandBezahlt: '', versandErstattung: '', neuerVersandpreis: '',
  bestellwert: '', erwarteteErstattung: '', saldoVorher: '', saldoNachher: '', refundHinterlegt: '',
  waehrung: '', finanzstatus: '', finanzstatusNachher: '', stornoBestaetigt: '', tagGesetzt: '',
  bearbeitetAm: '', quelle: ''
};

const zeile = (order, extra) => ({
  ...LEER,
  orderName: order.orderName,
  orderId: order.orderId,
  fall: order.fall || '',
  skus: (order.positionen || []).map(p => p.sku).join(' | '),
  menge: (order.positionen || []).reduce((s, p) => s + Number(p.menge || 0), 0),
  weiterePositionen: (order.weitere || []).map(p => `${p.sku || p.title} ×${p.menge}`).join(' | '),
  land: order.land || '',
  versandart: order.versandart || '',
  versandBezahlt: order.versandBezahlt ?? '',
  versandErstattung: order.versand ? order.versand.erstattung : '',
  neuerVersandpreis: order.versand ? order.versand.neuerPreis : '',
  bestellwert: order.bestellwert ?? '',
  erwarteteErstattung: order.erwarteteErstattung ?? '',
  saldoVorher: order.saldoVorher ?? '',
  waehrung: order.currency || '',
  finanzstatus: order.financialStatus || '',
  quelle: order.quelle || '',
  ...extra
});

const vorhaben = order => order.aktion === 'STORNO'
  ? 'würde storniert'
  : 'würde Buch entfernen' + (order.versand?.erstattung > 0
    ? `, Versanderstattung ${order.versand.erstattung.toFixed(2)}`
    : ', keine Versanderstattung');

const rows = [];
for (const order of gefunden) {
  const d = erledigt.find(e => e.orderId === order.orderId);
  if (config.trockenlauf) {
    rows.push(zeile(order, { status: 'TROCKENLAUF', grund: vorhaben(order) }));
  } else if (!d) {
    rows.push(zeile(order, { status: 'NICHT_VERARBEITET', grund: 'Test-Limiter aktiv oder Lauf abgebrochen' }));
  } else {
    const ok = d.status === 'STORNIERT' || d.status === 'ENTFERNT';
    rows.push(zeile(order, {
      status: d.status,
      grund: d.grund,
      saldoNachher: d.saldoNachher ?? '',
      refundHinterlegt: d.refundHinterlegt ?? '',
      finanzstatusNachher: d.finanzstatusNachher || '',
      stornoBestaetigt: d.status === 'STORNIERT' ? (d.stornoBestaetigt ? 'ja' : 'nein') : '',
      tagGesetzt: ok ? (d.tagGesetzt ? 'ja' : ('nein ' + (d.tagFehler || '')).trim()) : '',
      bearbeitetAm: d.bearbeitetAm
    }));
  }
}

for (const s of skipped) {
  rows.push(zeile(s, { status: s.status, grund: s.grund }));
}

return rows.map(r => ({ json: r }));

// TESTGATE: nur Bestellungen mit diesem Namens-Präfix in den API-Loop schicken.
// Für den Vollauf diesen Node deaktivieren oder löschen.
const PRAEFIX = 'BB-';

const treffer = $input.all().filter(i => String(i.json.orderName || '').startsWith(PRAEFIX));
if (!treffer.length) {
  throw new Error(`Test-Filter: keine Bestellung mit Präfix "${PRAEFIX}" in der CSV`);
}
return treffer;
